package com.example.procastinator.dao;

import com.example.procastinator.model.Recompensa;
import com.example.procastinator.model.StatusTarefa;
import com.example.procastinator.model.Tarefa;
import com.example.procastinator.util.HibernateUtil;
import org.hibernate.Session;
import org.hibernate.Transaction;

import java.time.LocalDateTime;
import java.util.List;

public class RecompensaDAO {

    public List<Recompensa> listarTodos() {
        throw new UnsupportedOperationException("Use listarPorUsuario(Integer)");
    }

    public List<Recompensa> listarPorUsuario(Integer usuarioId) {
        if (usuarioId == null) {
            return List.of();
        }
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            return session.createQuery(
                            "select r from com.example.procastinator.model.Recompensa r " +
                                    "left join fetch r.tarefa t " +
                                    "where t.usuario.id = :usuarioId " +
                                    "order by r.dataConquista desc, r.id desc",
                            Recompensa.class)
                    .setParameter("usuarioId", usuarioId)
                    .list();
        }
    }

    public Recompensa buscarPorId(Integer id) {
        throw new UnsupportedOperationException("Use buscarPorId(Integer, Integer)");
    }

    public Recompensa buscarPorId(Integer id, Integer usuarioId) {
        if (id == null || usuarioId == null) {
            return null;
        }
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            return session.createQuery(
                            "select r from com.example.procastinator.model.Recompensa r " +
                                    "left join fetch r.tarefa t " +
                                    "where r.id = :id and t.usuario.id = :usuarioId",
                            Recompensa.class)
                    .setParameter("id", id)
                    .setParameter("usuarioId", usuarioId)
                    .uniqueResult();
        }
    }

    public List<Recompensa> listarMudancasDeColunaDaTarefa(Integer tarefaId) {
        if (tarefaId == null) {
            return List.of();
        }
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            return session.createQuery(
                            "select r from com.example.procastinator.model.Recompensa r " +
                                    "where r.tarefa.id = :tarefaId " +
                                    "and (r.titulo like 'Subiu para %' or r.titulo like 'Chegou em %') " +
                                    "order by r.dataConquista asc, r.id asc",
                            Recompensa.class)
                    .setParameter("tarefaId", tarefaId)
                    .list();
        }
    }

    public Recompensa salvar(String titulo, String descricao) {
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            Transaction tx = session.beginTransaction();
            Recompensa recompensa = new Recompensa();
            String tituloNormalizado = normalizarTitulo(titulo);
            String descricaoNormalizada = normalizarDescricao(descricao);
            Tarefa tarefa = buscarTarefaPadrao(session);
            recompensa.setTitulo(tituloNormalizado);
            recompensa.setDescricao(descricaoNormalizada);
            recompensa.setTarefa(tarefa);
            recompensa.setPontos(calcularPontos(tarefa, tituloNormalizado, descricaoNormalizada));
            recompensa.setDataConquista(LocalDateTime.now());
            session.persist(recompensa);
            tx.commit();
            return carregarDetalhada(session, recompensa.getId());
        }
    }

    public Recompensa atualizar(Integer id, String titulo, String descricao) {
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            Transaction tx = session.beginTransaction();
            Recompensa recompensa = session.find(Recompensa.class, id);
            if (recompensa == null) {
                tx.rollback();
                return null;
            }

            String tituloNormalizado = normalizarTitulo(titulo);
            String descricaoNormalizada = normalizarDescricao(descricao);
            Tarefa tarefa = recompensa.getTarefa();
            if (tarefa == null) {
                tarefa = buscarTarefaPadrao(session);
            }
            recompensa.setTitulo(tituloNormalizado);
            recompensa.setDescricao(descricaoNormalizada);
            recompensa.setTarefa(tarefa);
            recompensa.setPontos(calcularPontos(tarefa, tituloNormalizado, descricaoNormalizada));

            tx.commit();
            return carregarDetalhada(session, recompensa.getId());
        }
    }

    public boolean excluir(Integer id) {
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            Transaction tx = session.beginTransaction();
            Recompensa recompensa = session.find(Recompensa.class, id);
            if (recompensa == null) {
                tx.rollback();
                return false;
            }

            session.remove(recompensa);
            tx.commit();
            return true;
        }
    }

    private Recompensa carregarDetalhada(Session session, Integer id) {
        return session.createQuery(
                        "select r from com.example.procastinator.model.Recompensa r " +
                                "left join fetch r.tarefa " +
                                "where r.id = :id",
                        Recompensa.class)
                .setParameter("id", id)
                .uniqueResult();
    }

    private Tarefa buscarTarefaPadrao(Session session) {
        return session.createQuery("from Tarefa t order by t.id desc", Tarefa.class)
                .setMaxResults(1)
                .uniqueResult();
    }

    private String normalizarTitulo(String titulo) {
        if (titulo == null || titulo.isBlank()) {
            return "Recompensa sem titulo";
        }
        return titulo.trim();
    }

    private String normalizarDescricao(String descricao) {
        if (descricao == null) {
            return "";
        }
        return descricao.trim();
    }

    private int calcularPontos(Tarefa tarefa, String titulo, String descricao) {
        int pontosBase = 8;
        if (tarefa != null && tarefa.getStatus() != null) {
            if (tarefa.getStatus() == StatusTarefa.BACKLOG) {
                pontosBase = 6;
            } else if (tarefa.getStatus() == StatusTarefa.ESPERANDO) {
                pontosBase = 12;
            } else if (tarefa.getStatus() == StatusTarefa.QUASE_FIZ) {
                pontosBase = 18;
            }
        }

        int bonusTitulo = Math.min(5, Math.max(0, titulo.length() / 12));
        int bonusDescricao = Math.min(7, Math.max(0, descricao.length() / 30));
        int total = pontosBase + bonusTitulo + bonusDescricao;
        int limitado = Math.min(50, total);
        return -limitado;
    }
}

package com.example.procastinator.dao;

import com.example.procastinator.model.Recompensa;
import com.example.procastinator.model.StatusTarefa;
import com.example.procastinator.model.Tarefa;
import com.example.procastinator.util.HibernateUtil;
import org.hibernate.Session;
import org.hibernate.Transaction;

import java.time.LocalDateTime;
import java.util.List;

public class RecompensaDAO {

    public List<Recompensa> listarTodos() {
        throw new UnsupportedOperationException("Use listarPorUsuario(Integer)");
    }

    public List<Recompensa> listarPorUsuario(Integer usuarioId) {
        if (usuarioId == null) {
            return List.of();
        }
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            return session.createQuery(
                            "select distinct r from com.example.procastinator.model.Recompensa r " +
                                    "left join fetch r.tarefa t " +
                                    "left join fetch r.usuario u " +
                                    "where (coalesce(u.id, -1) = :usuarioId or coalesce(t.usuario.id, -1) = :usuarioId) " +
                                    "order by r.dataConquista desc, r.id desc",
                            Recompensa.class)
                    .setParameter("usuarioId", usuarioId)
                    .list();
        }
    }

    public Recompensa buscarPorId(Integer id) {
        throw new UnsupportedOperationException("Use buscarPorId(Integer, Integer)");
    }

    public Recompensa buscarPorId(Integer id, Integer usuarioId) {
        if (id == null || usuarioId == null) {
            return null;
        }
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            return session.createQuery(
                            "select r from com.example.procastinator.model.Recompensa r " +
                                    "left join fetch r.tarefa t " +
                                    "left join fetch r.usuario u " +
                                    "where r.id = :id and (coalesce(u.id, -1) = :usuarioId or coalesce(t.usuario.id, -1) = :usuarioId)",
                            Recompensa.class)
                    .setParameter("id", id)
                    .setParameter("usuarioId", usuarioId)
                    .uniqueResult();
        }
    }

    public List<Recompensa> listarMudancasDeColunaDaTarefa(Integer tarefaId) {
        if (tarefaId == null) {
            return List.of();
        }
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            return session.createQuery(
                            "select r from com.example.procastinator.model.Recompensa r " +
                                    "where r.tarefa.id = :tarefaId " +
                                    "and (r.titulo like 'Subiu para %' or r.titulo like 'Chegou em %') " +
                                    "order by r.dataConquista asc, r.id asc",
                            Recompensa.class)
                    .setParameter("tarefaId", tarefaId)
                    .list();
        }
    }

    public Recompensa salvar(String titulo, String descricao) {
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            Transaction tx = session.beginTransaction();
            Recompensa recompensa = new Recompensa();
            String tituloNormalizado = normalizarTitulo(titulo);
            String descricaoNormalizada = normalizarDescricao(descricao);
            Tarefa tarefa = buscarTarefaPadrao(session);
            recompensa.setTitulo(tituloNormalizado);
            recompensa.setDescricao(descricaoNormalizada);
            recompensa.setTarefa(tarefa);
            recompensa.setUsuario(tarefa != null ? tarefa.getUsuario() : null);
            recompensa.setPontos(calcularPontos(tarefa, tituloNormalizado, descricaoNormalizada));
            recompensa.setDataConquista(LocalDateTime.now());
            session.persist(recompensa);
            tx.commit();
            return carregarDetalhada(session, recompensa.getId());
        }
    }

    public Recompensa atualizar(Integer id, String titulo, String descricao) {
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            Transaction tx = session.beginTransaction();
            Recompensa recompensa = session.find(Recompensa.class, id);
            if (recompensa == null) {
                tx.rollback();
                return null;
            }

            String tituloNormalizado = normalizarTitulo(titulo);
            String descricaoNormalizada = normalizarDescricao(descricao);
            Tarefa tarefa = recompensa.getTarefa();
            if (tarefa == null) {
                tarefa = buscarTarefaPadrao(session);
            }
            recompensa.setTitulo(tituloNormalizado);
            recompensa.setDescricao(descricaoNormalizada);
            recompensa.setTarefa(tarefa);
            recompensa.setUsuario(tarefa != null ? tarefa.getUsuario() : recompensa.getUsuario());
            recompensa.setPontos(calcularPontos(tarefa, tituloNormalizado, descricaoNormalizada));

            tx.commit();
            return carregarDetalhada(session, recompensa.getId());
        }
    }

    public boolean excluir(Integer id) {
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            Transaction tx = session.beginTransaction();
            Recompensa recompensa = session.find(Recompensa.class, id);
            if (recompensa == null) {
                tx.rollback();
                return false;
            }

            session.remove(recompensa);
            tx.commit();
            return true;
        }
    }

    private Recompensa carregarDetalhada(Session session, Integer id) {
        return session.createQuery(
                        "select r from com.example.procastinator.model.Recompensa r " +
                                "left join fetch r.tarefa " +
                                "where r.id = :id",
                        Recompensa.class)
                .setParameter("id", id)
                .uniqueResult();
    }

    private Tarefa buscarTarefaPadrao(Session session) {
        return session.createQuery("from Tarefa t order by t.id desc", Tarefa.class)
                .setMaxResults(1)
                .uniqueResult();
    }

    private String normalizarTitulo(String titulo) {
        if (titulo == null || titulo.isBlank()) {
            return "Recompensa sem titulo";
        }
        return titulo.trim();
    }

    private String normalizarDescricao(String descricao) {
        if (descricao == null) {
            return "";
        }
        return descricao.trim();
    }

    private int calcularPontos(Tarefa tarefa, String titulo, String descricao) {
        int pontosBase = 8;
        if (tarefa != null && tarefa.getStatus() != null) {
            if (tarefa.getStatus() == StatusTarefa.BACKLOG) {
                pontosBase = 6;
            } else if (tarefa.getStatus() == StatusTarefa.ESPERANDO) {
                pontosBase = 12;
            } else if (tarefa.getStatus() == StatusTarefa.QUASE_FIZ) {
                pontosBase = 18;
            }
        }

        int bonusTitulo = Math.min(5, Math.max(0, titulo.length() / 12));
        int bonusDescricao = Math.min(7, Math.max(0, descricao.length() / 30));
        int total = pontosBase + bonusTitulo + bonusDescricao;
        int limitado = Math.min(50, total);
        return -limitado;
    }
}

package com.example.procastinator.dao;

import com.example.procastinator.model.Categoria;
import com.example.procastinator.model.Historico;
import com.example.procastinator.model.Recompensa;
import com.example.procastinator.model.StatusTarefa;
import com.example.procastinator.model.Tarefa;
import com.example.procastinator.model.Usuario;
import com.example.procastinator.model.Xingamento;
import com.example.procastinator.util.HibernateUtil;
import org.hibernate.Session;
import org.hibernate.Transaction;

import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

public class TarefaDAO implements GenericDAO<Tarefa, Integer> {

    @Override
    public void salvar(Tarefa obj) {
        throw new UnsupportedOperationException("Use salvar(Tarefa, Integer usuarioId)");
    }

    public void salvar(Tarefa obj, Integer usuarioId) {
        if (usuarioId == null) {
            throw new IllegalArgumentException("usuarioId");
        }
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            Transaction tx = session.beginTransaction();
            obj.setCategoria(resolveCategoria(session, obj.getCategoria()));
            obj.setUsuario(session.getReference(Usuario.class, usuarioId));
            List<Xingamento> xingamentos = resolveXingamentos(session, obj.getXingamentos());
            if (xingamentos.isEmpty()) {
                xingamentos = carregarXingamentosPadrao(session);
            }
            obj.setXingamentos(xingamentos);
            session.persist(obj);
            registrarHistorico(session, obj, "CRIACAO", usuarioId);
            tx.commit();
        }
    }

    @Override
    public Tarefa buscarPorId(Integer id) {
        throw new UnsupportedOperationException("Use buscarPorId(Integer, Integer)");
    }

    public Tarefa buscarPorId(Integer id, Integer usuarioId) {
        if (id == null || usuarioId == null) {
            return null;
        }
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            return session.createQuery(
                            "select distinct t from Tarefa t " +
                                    "left join fetch t.categoria " +
                                    "left join fetch t.xingamentos " +
                                    "where t.id = :id and t.usuario.id = :usuarioId", Tarefa.class)
                    .setParameter("id", id)
                    .setParameter("usuarioId", usuarioId)
                    .uniqueResult();
        }
    }

    @Override
    public List<Tarefa> listarTodos() {
        throw new UnsupportedOperationException("Use listarPorUsuario(Integer)");
    }

    public List<Tarefa> listarPorUsuario(Integer usuarioId) {
        if (usuarioId == null) {
            return List.of();
        }
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            return session.createQuery(
                            "select distinct t from Tarefa t " +
                                    "left join fetch t.categoria " +
                                    "left join fetch t.xingamentos " +
                                    "where t.usuario.id = :usuarioId " +
                                    "order by t.id desc", Tarefa.class)
                    .setParameter("usuarioId", usuarioId)
                    .list();
        }
    }

    @Override
    public void atualizar(Tarefa obj) {
        throw new UnsupportedOperationException("Use atualizar(Tarefa, Integer usuarioId)");
    }

    public void atualizar(Tarefa obj, Integer usuarioId) {
        if (usuarioId == null || obj.getId() == null) {
            return;
        }
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            Transaction tx = session.beginTransaction();
            Tarefa atual = buscarTarefaDoUsuario(session, obj.getId(), usuarioId);
            if (atual != null) {
                StatusTarefa statusAnterior = atual.getStatus();
                if (obj.getTitulo() != null) {
                    atual.setTitulo(obj.getTitulo());
                }
                if (obj.getDescricao() != null) {
                    atual.setDescricao(obj.getDescricao());
                }
                if (obj.getStatus() != null) {
                    atual.setStatus(obj.getStatus());
                }
                if (obj.getDataPrazo() != null) {
                    atual.setDataPrazo(obj.getDataPrazo());
                }
                if (obj.getCategoria() != null) {
                    atual.setCategoria(resolveCategoria(session, obj.getCategoria()));
                }
                if (obj.getXingamentos() != null) {
                    atual.setXingamentos(resolveXingamentos(session, obj.getXingamentos()));
                }
                session.merge(atual);
                registrarHistorico(session, atual, "ATUALIZACAO", usuarioId);
                registrarRecompensaPorStatus(session, atual, statusAnterior, atual.getStatus());
            }
            tx.commit();
        }
    }

    @Override
    public void deletar(Integer id) {
        throw new UnsupportedOperationException("Use deletar(Integer, Integer)");
    }

    public void deletar(Integer id, Integer usuarioId) {
        if (id == null || usuarioId == null) {
            return;
        }
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            Transaction tx = session.beginTransaction();
            try {
                Tarefa tarefa = buscarTarefaDoUsuario(session, id, usuarioId);
                if (tarefa != null) {
                    session.createMutationQuery(
                                    "update Historico h set h.tarefa = null where h.tarefa.id = :id")
                            .setParameter("id", id)
                            .executeUpdate();
                    session.createMutationQuery(
                                    "update Recompensa r set r.tarefa = null where r.tarefa.id = :id")
                            .setParameter("id", id)
                            .executeUpdate();
                    session.createNativeQuery("delete from tarefa_xingamento where id_tarefa = :id")
                            .setParameter("id", id)
                            .executeUpdate();
                    registrarHistorico(session, tarefa, "EXCLUSAO", usuarioId);
                    session.remove(tarefa);
                }
                tx.commit();
            } catch (RuntimeException ex) {
                if (tx != null && tx.isActive()) {
                    tx.rollback();
                }
                throw ex;
            }
        }
    }

    public void atualizarStatus(Integer id, StatusTarefa status, Integer usuarioId) {
        if (id == null || usuarioId == null) {
            return;
        }
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            Transaction tx = session.beginTransaction();
            Tarefa tarefa = buscarTarefaDoUsuario(session, id, usuarioId);
            if (tarefa != null) {
                StatusTarefa statusAnterior = tarefa.getStatus();
                tarefa.setStatus(status);
                session.merge(tarefa);
                registrarHistorico(session, tarefa, "STATUS", usuarioId);
                registrarRecompensaPorStatus(session, tarefa, statusAnterior, status);
            }
            tx.commit();
        }
    }

    private Tarefa buscarTarefaDoUsuario(Session session, Integer id, Integer usuarioId) {
        return session.createQuery(
                        "from Tarefa t where t.id = :id and t.usuario.id = :usuarioId", Tarefa.class)
                .setParameter("id", id)
                .setParameter("usuarioId", usuarioId)
                .uniqueResult();
    }

    private void registrarRecompensaPorStatus(Session session, Tarefa tarefa, StatusTarefa anterior, StatusTarefa novo) {
        if (tarefa == null || novo == null || novo == anterior) {
            return;
        }

        int pontos;
        String titulo;
        if (novo == StatusTarefa.ESPERANDO) {
            pontos = -5;
            titulo = "Subiu para Esperando";
        } else if (novo == StatusTarefa.QUASE_FIZ) {
            pontos = -10;
            titulo = "Chegou em Quase Fiz";
        } else {
            return;
        }

        Recompensa recompensa = new Recompensa();
        recompensa.setTitulo(titulo);
        recompensa.setDescricao("Movimentacao da tarefa: " + (tarefa.getTitulo() == null ? "Sem titulo" : tarefa.getTitulo()));
        recompensa.setPontos(pontos);
        recompensa.setDataConquista(LocalDateTime.now());
        recompensa.setTarefa(tarefa);
        session.persist(recompensa);
    }

    private Categoria resolveCategoria(Session session, Categoria categoria) {
        if (categoria == null) {
            return ensureDefaultCategoria(session);
        }
        if (categoria.getId() != null) {
            Categoria persistent = session.find(Categoria.class, categoria.getId());
            if (persistent != null) {
                return persistent;
            }
        }
        if (categoria.getNome() != null && !categoria.getNome().isBlank()) {
            Categoria byName = session.createQuery(
                            "from Categoria c where lower(c.nome) = :nome", Categoria.class)
                    .setParameter("nome", categoria.getNome().toLowerCase())
                    .uniqueResult();
            if (byName != null) {
                return byName;
            }
        }
        Categoria novaCategoria = new Categoria();
        novaCategoria.setNome((categoria.getNome() == null || categoria.getNome().isBlank()) ? "GERAL" : categoria.getNome());
        session.persist(novaCategoria);
        session.flush();
        return novaCategoria;
    }

    private Categoria ensureDefaultCategoria(Session session) {
        Categoria categoria = session.find(Categoria.class, 1);
        if (categoria == null) {
            categoria = new Categoria();
            categoria.setNome("GERAL");
            session.persist(categoria);
            session.flush();
        }
        return categoria;
    }

    private List<Xingamento> resolveXingamentos(Session session, List<Xingamento> xingamentos) {
        List<Xingamento> resolved = new ArrayList<>();
        if (xingamentos == null) {
            return resolved;
        }
        for (Xingamento xingamento : xingamentos) {
            Xingamento persistent = null;
            if (xingamento.getId() != null) {
                persistent = session.find(Xingamento.class, xingamento.getId());
            }
            if (persistent == null && xingamento.getMensagem() != null && !xingamento.getMensagem().isBlank()) {
                persistent = session.createQuery(
                                "from Xingamento x where lower(x.mensagem) = :mensagem and lower(coalesce(x.tipo, '')) = :tipo",
                                Xingamento.class)
                        .setParameter("mensagem", xingamento.getMensagem().toLowerCase())
                        .setParameter("tipo", xingamento.getTipo() == null ? "" : xingamento.getTipo().toLowerCase())
                        .uniqueResult();
            }
            if (persistent != null) {
                resolved.add(persistent);
            }
        }
        return resolved;
    }

    private List<Xingamento> carregarXingamentosPadrao(Session session) {
        List<Xingamento> cadastrados = session.createQuery(
                        "from Xingamento x order by x.id", Xingamento.class)
                .list();
        if (cadastrados.isEmpty()) {
            return cadastrados;
        }

        List<Xingamento> padrao = new ArrayList<>();
        for (Xingamento item : cadastrados) {
            String tipo = item.getTipo() == null ? "" : item.getTipo().toUpperCase(Locale.ROOT);
            if ("XINGAMENTO".equals(tipo) || "ELOGIO".equals(tipo)) {
                padrao.add(item);
            }
        }
        return padrao.isEmpty() ? cadastrados : padrao;
    }

    private void registrarHistorico(Session session, Tarefa tarefa, String acao, Integer usuarioId) {
        Historico historico = new Historico();
        historico.setAcao(acao);
        historico.setDataHora(LocalDateTime.now());
        historico.setTarefa(tarefa);
        if (usuarioId != null) {
            historico.setUsuario(session.getReference(Usuario.class, usuarioId));
        }
        session.persist(historico);
    }
}

package com.example.procastinator.dao;

import com.example.procastinator.model.Categoria;
import com.example.procastinator.model.Historico;
import com.example.procastinator.model.Recompensa;
import com.example.procastinator.model.StatusTarefa;
import com.example.procastinator.model.Tarefa;
import com.example.procastinator.model.Usuario;
import com.example.procastinator.model.Xingamento;
import com.example.procastinator.util.HibernateUtil;
import org.hibernate.Session;
import org.hibernate.Transaction;

import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

public class TarefaDAO implements GenericDAO<Tarefa, Integer> {

    @Override
    public void salvar(Tarefa obj) {
        throw new UnsupportedOperationException("Use salvar(Tarefa, Integer usuarioId)");
    }

    public void salvar(Tarefa obj, Integer usuarioId) {
        if (usuarioId == null) {
            throw new IllegalArgumentException("usuarioId");
        }
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            Transaction tx = session.beginTransaction();
            obj.setCategoria(resolveCategoria(session, obj.getCategoria()));
            obj.setUsuario(session.getReference(Usuario.class, usuarioId));
            List<Xingamento> xingamentos = resolveXingamentos(session, obj.getXingamentos());
            if (xingamentos.isEmpty()) {
                xingamentos = carregarXingamentosPadrao(session, usuarioId);
            }
            obj.setXingamentos(xingamentos);
            session.persist(obj);
            registrarHistorico(session, obj, "CRIACAO", usuarioId);
            tx.commit();
        }
    }

    @Override
    public Tarefa buscarPorId(Integer id) {
        throw new UnsupportedOperationException("Use buscarPorId(Integer, Integer)");
    }

    public Tarefa buscarPorId(Integer id, Integer usuarioId) {
        if (id == null || usuarioId == null) {
            return null;
        }
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            return session.createQuery(
                            "select distinct t from Tarefa t " +
                                    "left join fetch t.categoria " +
                                    "left join fetch t.xingamentos " +
                                    "where t.id = :id and t.usuario.id = :usuarioId", Tarefa.class)
                    .setParameter("id", id)
                    .setParameter("usuarioId", usuarioId)
                    .uniqueResult();
        }
    }

    @Override
    public List<Tarefa> listarTodos() {
        throw new UnsupportedOperationException("Use listarPorUsuario(Integer)");
    }

    public List<Tarefa> listarPorUsuario(Integer usuarioId) {
        if (usuarioId == null) {
            return List.of();
        }
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            return session.createQuery(
                            "select distinct t from Tarefa t " +
                                    "left join fetch t.categoria " +
                                    "left join fetch t.xingamentos " +
                                    "where t.usuario.id = :usuarioId " +
                                    "order by t.id desc", Tarefa.class)
                    .setParameter("usuarioId", usuarioId)
                    .list();
        }
    }

    @Override
    public void atualizar(Tarefa obj) {
        throw new UnsupportedOperationException("Use atualizar(Tarefa, Integer usuarioId)");
    }

    public void atualizar(Tarefa obj, Integer usuarioId) {
        if (usuarioId == null || obj.getId() == null) {
            return;
        }
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            Transaction tx = session.beginTransaction();
            Tarefa atual = buscarTarefaDoUsuario(session, obj.getId(), usuarioId);
            if (atual != null) {
                StatusTarefa statusAnterior = atual.getStatus();
                if (obj.getTitulo() != null) {
                    atual.setTitulo(obj.getTitulo());
                }
                if (obj.getDescricao() != null) {
                    atual.setDescricao(obj.getDescricao());
                }
                if (obj.getStatus() != null) {
                    atual.setStatus(obj.getStatus());
                }
                if (obj.getDataPrazo() != null) {
                    atual.setDataPrazo(obj.getDataPrazo());
                }
                if (obj.getCategoria() != null) {
                    atual.setCategoria(resolveCategoria(session, obj.getCategoria()));
                }
                if (obj.getXingamentos() != null) {
                    atual.setXingamentos(resolveXingamentos(session, obj.getXingamentos()));
                }
                session.merge(atual);
                registrarHistorico(session, atual, "ATUALIZACAO", usuarioId);
                registrarRecompensaPorStatus(session, atual, statusAnterior, atual.getStatus(), usuarioId);
            }
            tx.commit();
        }
    }

    @Override
    public void deletar(Integer id) {
        throw new UnsupportedOperationException("Use deletar(Integer, Integer)");
    }

    public void deletar(Integer id, Integer usuarioId) {
        if (id == null || usuarioId == null) {
            return;
        }
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            Transaction tx = session.beginTransaction();
            try {
                Tarefa tarefa = buscarTarefaDoUsuario(session, id, usuarioId);
                if (tarefa != null) {
                    session.createMutationQuery(
                                    "update Historico h set h.tarefa = null where h.tarefa.id = :id")
                            .setParameter("id", id)
                            .executeUpdate();
                    session.createMutationQuery(
                                    "update Recompensa r set r.tarefa = null where r.tarefa.id = :id")
                            .setParameter("id", id)
                            .executeUpdate();
                    session.createNativeQuery("delete from tarefa_xingamento where id_tarefa = :id")
                            .setParameter("id", id)
                            .executeUpdate();
                    registrarHistorico(session, tarefa, "EXCLUSAO", usuarioId);
                    session.remove(tarefa);
                }
                tx.commit();
            } catch (RuntimeException ex) {
                if (tx != null && tx.isActive()) {
                    tx.rollback();
                }
                throw ex;
            }
        }
    }

    public void atualizarStatus(Integer id, StatusTarefa status, Integer usuarioId) {
        if (id == null || usuarioId == null) {
            return;
        }
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            Transaction tx = session.beginTransaction();
            Tarefa tarefa = buscarTarefaDoUsuario(session, id, usuarioId);
            if (tarefa != null) {
                StatusTarefa statusAnterior = tarefa.getStatus();
                tarefa.setStatus(status);
                session.merge(tarefa);
                registrarHistorico(session, tarefa, "STATUS", usuarioId);
                registrarRecompensaPorStatus(session, tarefa, statusAnterior, status, usuarioId);
            }
            tx.commit();
        }
    }

    private Tarefa buscarTarefaDoUsuario(Session session, Integer id, Integer usuarioId) {
        return session.createQuery(
                        "from Tarefa t where t.id = :id and t.usuario.id = :usuarioId", Tarefa.class)
                .setParameter("id", id)
                .setParameter("usuarioId", usuarioId)
                .uniqueResult();
    }

    private void registrarRecompensaPorStatus(Session session, Tarefa tarefa, StatusTarefa anterior, StatusTarefa novo, Integer usuarioId) {
        if (tarefa == null || novo == null || novo == anterior) {
            return;
        }

        int pontos;
        String titulo;
        if (novo == StatusTarefa.ESPERANDO) {
            pontos = -5;
            titulo = "Subiu para Esperando";
        } else if (novo == StatusTarefa.QUASE_FIZ) {
            pontos = -10;
            titulo = "Chegou em Quase Fiz";
        } else {
            return;
        }

        Recompensa recompensa = new Recompensa();
        recompensa.setTitulo(titulo);
        recompensa.setDescricao("Movimentacao da tarefa: " + (tarefa.getTitulo() == null ? "Sem titulo" : tarefa.getTitulo()));
        recompensa.setPontos(pontos);
        recompensa.setDataConquista(LocalDateTime.now());
        recompensa.setTarefa(tarefa);
        if (usuarioId != null) {
            recompensa.setUsuario(session.getReference(Usuario.class, usuarioId));
        }
        session.persist(recompensa);
    }

    private Categoria resolveCategoria(Session session, Categoria categoria) {
        if (categoria == null) {
            return ensureDefaultCategoria(session);
        }
        if (categoria.getId() != null) {
            Categoria persistent = session.find(Categoria.class, categoria.getId());
            if (persistent != null) {
                return persistent;
            }
        }
        if (categoria.getNome() != null && !categoria.getNome().isBlank()) {
            Categoria byName = session.createQuery(
                            "from Categoria c where lower(c.nome) = :nome", Categoria.class)
                    .setParameter("nome", categoria.getNome().toLowerCase())
                    .uniqueResult();
            if (byName != null) {
                return byName;
            }
        }
        Categoria novaCategoria = new Categoria();
        novaCategoria.setNome((categoria.getNome() == null || categoria.getNome().isBlank()) ? "GERAL" : categoria.getNome());
        session.persist(novaCategoria);
        session.flush();
        return novaCategoria;
    }

    private Categoria ensureDefaultCategoria(Session session) {
        Categoria categoria = session.find(Categoria.class, 1);
        if (categoria == null) {
            categoria = new Categoria();
            categoria.setNome("GERAL");
            session.persist(categoria);
            session.flush();
        }
        return categoria;
    }

    private List<Xingamento> resolveXingamentos(Session session, List<Xingamento> xingamentos) {
        List<Xingamento> resolved = new ArrayList<>();
        if (xingamentos == null) {
            return resolved;
        }
        for (Xingamento xingamento : xingamentos) {
            Xingamento persistent = null;
            if (xingamento.getId() != null) {
                persistent = session.find(Xingamento.class, xingamento.getId());
            }
            if (persistent == null && xingamento.getMensagem() != null && !xingamento.getMensagem().isBlank()) {
                persistent = session.createQuery(
                                "from Xingamento x where lower(x.mensagem) = :mensagem and lower(coalesce(x.tipo, '')) = :tipo",
                                Xingamento.class)
                        .setParameter("mensagem", xingamento.getMensagem().toLowerCase())
                        .setParameter("tipo", xingamento.getTipo() == null ? "" : xingamento.getTipo().toLowerCase())
                        .uniqueResult();
            }
            if (persistent != null) {
                resolved.add(persistent);
            }
        }
        return resolved;
    }

    private List<Xingamento> carregarXingamentosPadrao(Session session, Integer usuarioId) {
        List<Xingamento> cadastrados = session.createQuery(
                        "from Xingamento x where x.usuario.id = :usuarioId order by x.id", Xingamento.class)
                .setParameter("usuarioId", usuarioId)
                .list();
        if (cadastrados.isEmpty()) {
            return cadastrados;
        }

        List<Xingamento> padrao = new ArrayList<>();
        for (Xingamento item : cadastrados) {
            String tipo = item.getTipo() == null ? "" : item.getTipo().toUpperCase(Locale.ROOT);
            if ("XINGAMENTO".equals(tipo) || "ELOGIO".equals(tipo)) {
                padrao.add(item);
            }
        }
        return padrao.isEmpty() ? cadastrados : padrao;
    }

    private void registrarHistorico(Session session, Tarefa tarefa, String acao, Integer usuarioId) {
        Historico historico = new Historico();
        historico.setAcao(acao);
        historico.setDataHora(LocalDateTime.now());
        historico.setTarefa(tarefa);
        if (usuarioId != null) {
            historico.setUsuario(session.getReference(Usuario.class, usuarioId));
        }
        session.persist(historico);
    }
}

package com.example.procastinator.dao;

import com.example.procastinator.model.Xingamento;
import com.example.procastinator.util.HibernateUtil;
import org.hibernate.Session;
import org.hibernate.Transaction;

import java.util.List;
import java.util.Locale;

public class XingamentoDAO {

    public enum ExclusaoAvisoResultado {
        REMOVIDO,
        NAO_ENCONTRADO,
        VINCULADO_A_TAREFA
    }

    public List<Xingamento> listarTodos() {
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            return session.createQuery("from Xingamento x order by x.id desc", Xingamento.class).list();
        }
    }

    public Xingamento buscarPorId(Integer id) {
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            return session.find(Xingamento.class, id);
        }
    }

    public Xingamento salvarAviso(String mensagem, String tipo) {
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            Transaction tx = session.beginTransaction();
            Xingamento aviso = new Xingamento();
            aviso.setMensagem(mensagem);
            aviso.setTipo(normalizarTipo(tipo));
            session.persist(aviso);
            tx.commit();
            return session.find(Xingamento.class, aviso.getId());
        }
    }

    public Xingamento atualizarAviso(Integer id, String mensagem, String tipo) {
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            Transaction tx = session.beginTransaction();
            Xingamento aviso = session.find(Xingamento.class, id);
            if (aviso == null) {
                tx.rollback();
                return null;
            }

            aviso.setMensagem(mensagem);
            aviso.setTipo(normalizarTipo(tipo));
            tx.commit();
            return session.find(Xingamento.class, id);
        }
    }

    public ExclusaoAvisoResultado excluirAviso(Integer id) {
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            Transaction tx = session.beginTransaction();
            Xingamento aviso = session.find(Xingamento.class, id);
            if (aviso == null) {
                tx.rollback();
                return ExclusaoAvisoResultado.NAO_ENCONTRADO;
            }

            Number totalVinculos = (Number) session.createNativeQuery(
                            "select count(*) from tarefa_xingamento where id_xingamento = :id")
                    .setParameter("id", id)
                    .uniqueResult();
            int vinculos = totalVinculos == null ? 0 : totalVinculos.intValue();
            if (vinculos > 0) {
                tx.rollback();
                return ExclusaoAvisoResultado.VINCULADO_A_TAREFA;
            }

            session.remove(aviso);
            tx.commit();
            return ExclusaoAvisoResultado.REMOVIDO;
        }
    }

    private String normalizarTipo(String tipo) {
        if (tipo == null || tipo.isBlank()) {
            return "XINGAMENTO";
        }
        String normalizado = tipo.trim().toUpperCase(Locale.ROOT);
        return "ELOGIO".equals(normalizado) ? "ELOGIO" : "XINGAMENTO";
    }
}

package com.example.procastinator.dao;

import com.example.procastinator.model.Usuario;
import com.example.procastinator.model.Xingamento;
