        StatusTarefa status = parseStatus(req.getParameter("status"));

        if (status == StatusTarefa.ESPERANDO || status == StatusTarefa.QUASE_FIZ) {
            Integer ultimoId = (Integer) session.getAttribute("ultimoXingamentoId");
