                if (xingamento.getMensagem() != null) {
                    FlashMensagens.xingamento(session, xingamento.getMensagem());
                }
            } else {
                dao.atualizarStatus(id, status, usuarioId);
            }
        } else {
            dao.atualizarStatus(id, status, usuarioId);
        }
        FlashMensagens.toast(session, "Status atualizado.");
    }

    private void excluir(HttpServletRequest req, Integer usuarioId) {
        Integer id = parseId(req.getParameter("id"));
        if (id == null) {
            throw new IllegalArgumentException("id");
        }
        dao.deletar(id, usuarioId);
        FlashMensagens.toast(req.getSession(), "Tarefa removida.");
    }

    private static Categoria parseCategoriaNome(String nome) {
        if (nome == null || nome.isBlank()) {
            return null;
        }
        Categoria c = new Categoria();
        c.setNome(nome);
        return c;
    }

    private static String trim(String s) {
        return s == null ? "" : s.trim();
    }

    private static Integer parseId(String raw) {
        if (raw == null || raw.isBlank()) {
            return null;
        }
        try {
            return Integer.parseInt(raw.trim());
        } catch (NumberFormatException e) {
            return null;
        }
    }

    private static StatusTarefa parseStatus(String raw) {
        if (raw == null || raw.isBlank()) {
            return StatusTarefa.BACKLOG;
        }
        return StatusTarefa.valueOf(raw.trim().toUpperCase(Locale.ROOT));
    }

    private static LocalDate parsePrazo(String raw) {
        if (raw == null || raw.isBlank()) {
            return null;
        }
        String n = raw.trim();
        if (n.length() > 10) {
            n = n.substring(0, 10);
        }
        return LocalDate.parse(n);
    }
}

package com.example.procastinator.web;

import com.example.procastinator.dao.XingamentoDAO;
import com.example.procastinator.model.Xingamento;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.ThreadLocalRandom;

public final class IncentivoSorteador {

    private final XingamentoDAO dao = new XingamentoDAO();

    public Xingamento sortearElogio() {
        return sortearPorTipo("ELOGIO", null);
    }

    public Xingamento sortearXingamento(Integer ultimoId) {
        return sortearPorTipo("XINGAMENTO", ultimoId);
    }

    private Xingamento sortearPorTipo(String tipo, Integer ultimoId) {
        List<Xingamento> candidatos = new ArrayList<>();
        for (Xingamento item : dao.listarTodos()) {
            String t = item.getTipo() == null ? "" : item.getTipo().toUpperCase(Locale.ROOT);
            if (tipo.equals(t)) {
                candidatos.add(item);
            }
        }
        if (candidatos.isEmpty()) {
            return null;
        }
        if (candidatos.size() > 1 && ultimoId != null) {
            List<Xingamento> semRepeticao = candidatos.stream()
                    .filter(x -> !ultimoId.equals(x.getId()))
                    .toList();
            if (!semRepeticao.isEmpty()) {
                candidatos = new ArrayList<>(semRepeticao);
            }
        }
        int idx = ThreadLocalRandom.current().nextInt(candidatos.size());
        return candidatos.get(idx);
    }
}

package com.example.procastinator.web;

import com.example.procastinator.dao.XingamentoDAO;
import com.example.procastinator.model.Xingamento;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.ThreadLocalRandom;

public final class IncentivoSorteador {

    private final XingamentoDAO dao = new XingamentoDAO();

    public Xingamento sortearElogio(Integer usuarioId) {
        return sortearPorTipo("ELOGIO", null, usuarioId);
    }

    public Xingamento sortearXingamento(Integer ultimoId, Integer usuarioId) {
        return sortearPorTipo("XINGAMENTO", ultimoId, usuarioId);
    }

    private Xingamento sortearPorTipo(String tipo, Integer ultimoId, Integer usuarioId) {
        List<Xingamento> candidatos = new ArrayList<>();
        for (Xingamento item : dao.listarPorUsuario(usuarioId)) {
            String t = item.getTipo() == null ? "" : item.getTipo().toUpperCase(Locale.ROOT);
            if (tipo.equals(t)) {
                candidatos.add(item);
            }
        }
        if (candidatos.isEmpty()) {
            return null;
        }
        if (candidatos.size() > 1 && ultimoId != null) {
            List<Xingamento> semRepeticao = candidatos.stream()
                    .filter(x -> !ultimoId.equals(x.getId()))
                    .toList();
            if (!semRepeticao.isEmpty()) {
                candidatos = new ArrayList<>(semRepeticao);
            }
        }
        int idx = ThreadLocalRandom.current().nextInt(candidatos.size());
        return candidatos.get(idx);
    }
}
